mapper.select:
SELECT aar.id, aar.question_id AS questionId, q.title AS questionTitle, aar.assist_type AS assistType, aar.user_input AS userInput, aar.content, aar.model_name AS modelName, aar.status, aar.error_message AS errorMessage, aar.latency_ms AS latencyMs, aar.create_time AS createTime FROM ai_assist_record aar LEFT JOIN question q ON q.id = aar.question_id
aar.user_id = #{userId} AND aar.question_id = #{questionId}
AND aar.id < #{cursor}
ORDER BY aar.id DESC LIMIT #{limit}
